window.CS50KZ_MATH_EXAM.ode = [{"id":"m9-1-tf-basic:0","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"$y''+4y=0$ теңдеуі екінші ретті, сызықты.","a":true,"e":"Ақиқат: ең жоғары туынды $y''$, ал $y$ мен $y''$ бірінші дәрежеде, коэффициенттері тұрақты."},{"id":"m9-1-tf-basic:1","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"$y'=y^2$ сызықтық теңдеу.","a":false,"e":"Жалған: $y^2$ - белгісіз функцияның квадраты, сондықтан теңдеу сызықтық емес."},{"id":"m9-1-tf-basic:2","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"$y=Ce^{3x}$ әулетінің әрбір функциясы $y'=3y$ теңдеуін қанағаттандырады.","a":true,"e":"Ақиқат: $y'=3Ce^{3x}=3y$."},{"id":"m9-1-tf-basic:3","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"$n$-ші ретті теңдеудің жалпы шешімінде $n+1$ еркін тұрақты болады.","a":false,"e":"Жалған: $n$-ші ретті теңдеудің жалпы шешімінде дәл $n$ еркін тұрақты болады."},{"id":"m9-1-tf-basic:4","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"Бағыт өрісінде изоклин бойында барлық шешімнің еңісі бірдей.","a":true,"e":"Ақиқат: изоклин - $f(x,y)=c$ нүктелері жиыны, онда шешімнің еңісі $y'=f=c$."},{"id":"m9-1-order-lin:0","l":1,"lvl":"easy","type":"choice","ctx":"Ретін және түрін анықтау. Дұрыс жауапты таңдаңыз.","q":"$y'''-2y'+y=\\sin x$ теңдеуінің реті қандай?","o":["1","2","3","4"],"a":2,"e":"Ең жоғары туынды $y'''$: үшінші ретті."},{"id":"m9-1-order-lin:1","l":1,"lvl":"easy","type":"choice","ctx":"Ретін және түрін анықтау. Дұрыс жауапты таңдаңыз.","q":"Төмендегі теңдеулердің қайсысы сызықты <em>емес</em>? (Бірнешеуі болуы мүмкін.)","o":["$y'+xy=e^{x}$","$y''+y'\\,y=0$","$y'=\\sqrt{y}$","$xy'-2y=x^3$"],"a":[1,2],"e":"$y'y$ көбейтіндісі мен $\\sqrt{y}$ сызықтық емес. Қалған екеуі $y,y'$ бойынша бірінші дәрежелі."},{"id":"m9-1-check-c:0","l":1,"lvl":"easy","type":"num","ctx":"Бастапқы шарт бойынша тұрақты. Жауапты санмен немесе өрнекпен жазыңыз (мысалы, 2*exp(3)).","q":"$y'=3y$, $y(0)=2$. $y(1)=\\ ?$","a":"2*exp(3)"},{"id":"m9-1-check-c:1","l":1,"lvl":"easy","type":"num","ctx":"Бастапқы шарт бойынша тұрақты. Жауапты санмен немесе өрнекпен жазыңыз (мысалы, 2*exp(3)).","q":"$y'=-y$, $y(0)=5$. $y(0)$-ден кейін $x=\\ln5$ нүктесінде $y=\\ ?$","a":1},{"id":"m9-1-ivp-simple:0","l":1,"lvl":"easy","type":"expr","ctx":"Қарапайым бастапқы есеп. Өрнекті $x$ арқылы жазыңыз.","q":"$y'=6x^2$, $y(1)=5$. $y(x)=\\ ?$","a":"2*x^3+3"},{"id":"m9-1-ivp-simple:1","l":1,"lvl":"easy","type":"expr","ctx":"Қарапайым бастапқы есеп. Өрнекті $x$ арқылы жазыңыз.","q":"$y'=\\cos x$, $y(\\pi)=2$. $y(x)=\\ ?$","a":"sin(x)+2"},{"id":"m9-1-isocline:0","l":1,"lvl":"medium","type":"expr","ctx":"Изоклин теңдеуі. Теңдеу ретінде жазыңыз (мысалы, y=x-2 ).","q":"$y'=x-y$ теңдеуінің $c=2$ изоклині.","eq":true,"a":"y=x-2"},{"id":"m9-1-isocline:1","l":1,"lvl":"medium","type":"expr","ctx":"Изоклин теңдеуі. Теңдеу ретінде жазыңыз (мысалы, y=x-2 ).","q":"$y'=2x+y$ теңдеуінің $c=0$ изоклині.","eq":true,"a":"y=-2*x"},{"id":"m9-1-slope-grid:0","l":1,"lvl":"easy","type":"matrix","ctx":"Еңістер торы. $y'=x\\,y$ теңдеуі үшін көрсетілген нүктелердегі еңістерді жазыңыз.","q":"$(1;1),\\ (2;1),\\ (1;3),\\ (-2;2)$ нүктелеріндегі еңістер (жол түрінде).","orient":"row","name":"$y'$:","a":[1,2,3,-4]},{"id":"m9-1-uniq-thm:0","l":1,"lvl":"medium","type":"choice","ctx":"Жалғыздық теоремасы қашан кепілдік береді?. Теорема 1.1 шарттарын тексеріңіз.","q":"Қай Коши есебінде $(0;0)$ маңында шешімнің <em>жалғыздығы</em> кепілденеді?","o":["$y'=y^{2/3}$, $y(0)=0$","$y'=\\sqrt{|y|}$, $y(0)=0$","$y'=y^3+x$, $y(0)=0$","$y'=\\sqrt{y}+1$, $y(0)=0$"],"a":2,"e":"Үшінші жағдайда $f=y^3+x$ және $f_y=3y^2$ барлық жерде үзіліссіз. Қалғандарында $f_y$ нөлде үзіліске ұшырайды, сондықтан теорема жалғыздыққа кепілдік бермейді (бірінші және екіншіде жалғыздық шынымен бұзылады)."},{"id":"m9-1-uniq-thm:1","l":1,"lvl":"medium","type":"choice","ctx":"Жалғыздық теоремасы қашан кепілдік береді?. Теорема 1.1 шарттарын тексеріңіз.","q":"$y'=y^2$, $y(0)=1$ шешімі $y=\\dfrac1{1-x}$. Ол қай аралықта анықталған (бастапқы нүктені қамтитын)?","o":["$(-\\infty;+\\infty)$","$(-\\infty;1)$","$(1;+\\infty)$","$[0;1]$"],"a":1,"e":"$x=0$ нүктесін қамтитын байланысты бөлік $(-\\infty;1)$, өйткені $x=1$ нүктесінде шешім шексіздікке кетеді."},{"id":"m9-1-uniq-region:0","l":1,"lvl":"medium","type":"interval","ctx":"Теорема қолданылатын облыс. Жауапты аралық түрінде жазыңыз (шексіздік - oo).","q":"$y'=\\sqrt{y-1}$ теңдеуінде $\\dfrac{\\partial f}{\\partial y}$ үзіліссіз болатын $y$ мәндерінің жиыны (бұл жиында әр бастапқы нүкте үшін шешім жалғыз).","a":"(1; oo)"},{"id":"m9-1-eliminate:0","l":1,"lvl":"hard","type":"expr","ctx":"Тұрақтыны жою. Нәтижені $x$ және $y$ арқылы жазыңыз.","q":"$y=Cx^3$ әулеті үшін $y'$-ті $x$ және $y$ арқылы өрнектеңіз (тұрақты жойылсын).","vars":["x","y"],"dom":[0.5,3],"a":"3*y/x"},{"id":"m9-1-euler-two:0","l":1,"lvl":"hard","type":"num","ctx":"Эйлер әдісінің екі қадамы. Жауапты ондық бөлшекпен жазыңыз.","q":"$y'=x+y$, $y(0)=1$, $h=0{,}1$. Эйлер әдісімен $y_2$ ($x=0{,}2$ кезіндегі жуық мән) қанша?","a":1.22,"tol":1e-06},{"id":"m9-1-euler-two:1","l":1,"lvl":"hard","type":"num","ctx":"Эйлер әдісінің екі қадамы. Жауапты ондық бөлшекпен жазыңыз.","q":"Сол есептің нақты шешімі $y=2e^{x}-x-1$. $x=0{,}2$ кезінде қателік $|y(0{,}2)-y_2|$ болсын. $1000\\cdot|y(0{,}2)-y_2|$ санын бүтінге дейін дөңгелектеңіз.","a":23,"tol":0.01},{"id":"m9-1-blowup:0","l":1,"lvl":"hard","type":"num","ctx":"Шешімнің «жарылу» уақыты. Жауапты санмен жазыңыз.","q":"$y'=y^2$, $y(0)=2$ шешімі шектеулі $x$ мәнінде шексіздікке кетеді. Сол $x$-ті табыңыз.","a":0.5},{"id":"m9-1-second-order:0","l":1,"lvl":"medium","type":"matrix","ctx":"Екі параметрлі әулет. $y=C_1\\cos x+C_2\\sin x$ әулеті берілген.","q":"$y(0)=3$, $y'(0)=-2$ шарттары бойынша $\\begin{pmatrix}C_1\\\\C_2\\end{pmatrix}$ векторын табыңыз.","name":"$C=$","a":[[3],[-2]]},{"id":"m9-1-tf-euler:0","l":1,"lvl":"medium","type":"tf","ctx":"Эйлер әдісі туралы. Әр пікірді бағалаңыз.","q":"Эйлер әдісінде $h$-ты екі есе кемітсе, жиынтық қателік шамамен екі есе кемиді.","a":true,"e":"Ақиқат: әдіс бірінші ретті, жиынтық қателік $O(h)$."},{"id":"m9-1-tf-euler:1","l":1,"lvl":"medium","type":"tf","ctx":"Эйлер әдісі туралы. Әр пікірді бағалаңыз.","q":"$y'=y$ үшін Эйлер әдісі әрдайым нақты шешімнен үлкен мән береді ($y_0>0$).","a":false,"e":"Жалған: $(1+h)^n<e^{nh}$, яғни Эйлер мәні нақты $e^{x}$-тен кіші."},{"id":"m9-1-tf-euler:2","l":1,"lvl":"medium","type":"tf","ctx":"Эйлер әдісі туралы. Әр пікірді бағалаңыз.","q":"Эйлер әдісінің бір қадамындағы қателік $O(h^2)$.","a":true,"e":"Ақиқат: Тейлор қатарынан тасталған мүше $\\frac{h^2}{2}y''$."},{"id":"m9-1-equilib:0","l":1,"lvl":"hard","type":"choice","ctx":"Тепе-теңдік шешімдері. Тепе-теңдік шешімдерін анықтаңыз.","q":"$y'=y(1-y)(y+2)$ теңдеуінің барлық тепе-теңдік шешімін белгілеңіз.","o":["$y\\equiv0$","$y\\equiv1$","$y\\equiv-2$","$y\\equiv2$","$y\\equiv-1$"],"a":[0,1,2],"e":"Оң жағы $y=0,\\,1,\\,-2$ нүктелерінде нөл болады. $y=2$ және $y=-1$ үшін оң жағы нөл емес."},{"id":"w55-q0","l":1,"lvl":"quiz","type":"choice","q":"y'' + 3y' − y³ = 0 теңдеуінің реті мен түрі қандай?","o":["1-ші ретті, сызықты","2-ші ретті, сызықтық емес","3-ші ретті, сызықты","2-ші ретті, сызықты"],"a":1,"e":"Ең жоғары туынды y'' - екінші рет. y³ мүшесі сызықтық емес, сондықтан теңдеу сызықтық емес."},{"id":"w55-q1","l":1,"lvl":"quiz","type":"choice","q":"y = Ce^(−2x) әулеті қай теңдеуді қанағаттандырады?","o":["y' = 2y","y' = −2y","y' = −2x","y'' = −2y"],"a":1,"e":"y' = −2Ce^(−2x) = −2y."},{"id":"w55-q2","l":1,"lvl":"quiz","type":"choice","q":"y' = 4y, y(0) = 3 есебінің шешімі қандай?","o":["3e^(4x)","4e^(3x)","3 + 4x","e^(4x) + 3"],"a":0,"e":"Жалпы шешім y = Ce^(4x), y(0) = C = 3."},{"id":"w55-q3","l":1,"lvl":"quiz","type":"choice","q":"Екінші ретті теңдеудің Коши есебіне қанша бастапқы шарт керек?","o":["1","2","3","шарт керек емес"],"a":1,"e":"Екі еркін тұрақты бар, сондықтан y(x₀) және y'(x₀) екі шарт беріледі."},{"id":"w55-q4","l":1,"lvl":"quiz","type":"choice","q":"y' = x − y теңдеуінің c = 3 изоклині қандай?","o":["y = x + 3","y = x − 3","y = 3x","y = 3 − x"],"a":1,"e":"x − y = 3 теңдеуінен y = x − 3."},{"id":"w55-q5","l":1,"lvl":"quiz","type":"choice","q":"y' = 3y^(2/3), y(0) = 0 есебінде жалғыздық неге бұзылады?","o":["f(x,y) үзілісті","f_y нөлде үзіледі","теңдеу сызықты","бастапқы шарт тым кіші"],"a":1,"e":"f_y = 2y^(−1/3) y = 0 нүктесінде үзіледі, Липшиц шарты орындалмайды: y ≡ 0 және y = x³ екеуі де шешім."},{"id":"w55-q6","l":1,"lvl":"quiz","type":"choice","q":"Эйлер әдісімен y' = x + y, y(0) = 1, h = 0,1 үшін y₁ қанша?","o":["1,0","1,1","1,2","1,21"],"a":1,"e":"y₁ = 1 + 0,1·(0 + 1) = 1,1."},{"id":"w55-q7","l":1,"lvl":"quiz","type":"choice","q":"Эйлер әдісінің жиынтық қателігі h-қа қалай тәуелді?","o":["h²-қа пропорционал","h-қа пропорционал","h-қа тәуелсіз","1/h-қа пропорционал"],"a":1,"e":"Бір қадамда қателік O(h²), қадам саны ≈ 1/h, жиынтығы O(h)."},{"id":"m9-2-tf-sep:0","l":2,"lvl":"easy","type":"tf","ctx":"Бөлінетін теңдеу ме?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"$y'=x\\,y^2$ теңдеуі айнымалылары бөлінетін теңдеу.","a":true,"e":"Ақиқат: $g=x$, $h=y^2$."},{"id":"m9-2-tf-sep:1","l":2,"lvl":"easy","type":"tf","ctx":"Бөлінетін теңдеу ме?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"$y'=x+y$ теңдеуі айнымалылары бөлінетін теңдеу.","a":false,"e":"Жалған: қосынды $g(x)h(y)$ көбейтіндісіне жіктелмейді."},{"id":"m9-2-tf-sep:2","l":2,"lvl":"easy","type":"tf","ctx":"Бөлінетін теңдеу ме?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"$y'=f(y)$ автономды теңдеуі әрдайым бөлінетін теңдеу.","a":true,"e":"Ақиқат: $g\\equiv1$, $h=f$."},{"id":"m9-2-tf-sep:3","l":2,"lvl":"easy","type":"tf","ctx":"Бөлінетін теңдеу ме?. Әр пікірдің ақиқат не жалған екенін белгілеңіз.","q":"Бөлу кезінде $h(y)=0$ шешімдері әрдайым жалпы шешімге кіреді.","a":false,"e":"Жалған: $y'=x(y^2-1)$ теңдеуінде $y\\equiv-1$ жалпы формуладан тыс қалады."},{"id":"m9-2-choice-sep:0","l":2,"lvl":"easy","type":"choice","ctx":"Бөлінетін теңдеулерді тану. Дұрыс жауаптарды белгілеңіз.","q":"Қайсысы айнымалылары бөлінетін теңдеу? (Бірнеше жауап мүмкін.)","o":["$y'=e^{x+y}$","$y'=\\sin(x+y)$","$y'=\\dfrac{x^2}{y}$","$y'=x-y^2$"],"a":[0,2],"e":"$e^{x+y}=e^{x}e^{y}$ және $\\dfrac{x^2}{y}=x^2\\cdot\\dfrac1y$ көбейтінді түрінде жазылады. $\\sin(x+y)$ және $x-y^2$ жіктелмейді."},{"id":"m9-2-num-simple:0","l":2,"lvl":"easy","type":"num","ctx":"Қарапайым бөлу. Жауапты санмен жазыңыз.","q":"$y'=3y^2$, $y(0)=1$ шешімі $y=\\dfrac{1}{1-3x}$. $y\\!\\left(\\tfrac16\\right)=\\ ?$","a":2},{"id":"m9-2-num-simple:1","l":2,"lvl":"easy","type":"num","ctx":"Қарапайым бөлу. Жауапты санмен жазыңыз.","q":"Сол шешім қай $x_*$ нүктесінде шексіздікке кетеді?","a":"1/3"},{"id":"m9-2-ivp-2xy:0","l":2,"lvl":"medium","type":"expr","ctx":"Бастапқы есепті шешу. Өрнекті $x$ арқылы жазыңыз.","q":"$y'=2xy$, $y(0)=3$. $y(x)=\\ ?$","a":"3*exp(x^2)"},{"id":"m9-2-ivp-2xy:1","l":2,"lvl":"medium","type":"expr","ctx":"Бастапқы есепті шешу. Өрнекті $x$ арқылы жазыңыз.","q":"$y'=\\dfrac{x}{y}$, $y(0)=2$, $y>0$. $y(x)=\\ ?$","a":"sqrt(x^2+4)"},{"id":"m9-2-num-halflife:0","l":2,"lvl":"medium","type":"num","ctx":"Жартылай ыдырау периоды. Жауапты ондық бөлшекпен жазыңыз (1 таңбаға дейін).","q":"Заттың массасы $4$ тәулікте $100$ г-нан $25$ г-ға дейін кемиді. Жартылай ыдырау периоды (тәулікпен)?","a":2},{"id":"m9-2-num-halflife:1","l":2,"lvl":"medium","type":"num","ctx":"Жартылай ыдырау периоды. Жауапты ондық бөлшекпен жазыңыз (1 таңбаға дейін).","q":"Сол затта $100$ г-нан $12{,}5$ г-ға дейін кему үшін қанша тәулік керек?","a":6},{"id":"m9-2-num-cooling:0","l":2,"lvl":"medium","type":"num","ctx":"Суу уақыты. Жауапты ондық бөлшекпен жазыңыз (1 таңбаға дейін).","q":"Орта температурасы $T_a=20^\\circ$C. Дене $100^\\circ$C-тан $60^\\circ$C-қа $10$ минутта суыды. Ол $30^\\circ$C-қа жету үшін барлығы қанша минут керек?","a":30,"tol":0.05},{"id":"m9-2-int-domain:0","l":2,"lvl":"medium","type":"interval","ctx":"Шешімнің өмір сүру облысы. Аралық түрінде жазыңыз; шексіздік - oo, квадрат түбір - sqrt.","q":"$y'=xy^2$, $y(0)=1$ шешімі $y=\\dfrac{2}{2-x^2}$. $x=0$ нүктесін қамтитын аралықты (шешім шектеусіз өсетін нүктелерге дейін) табыңыз.","a":"(-sqrt(2); sqrt(2))"},{"id":"m9-2-choice-lost:0","l":2,"lvl":"medium","type":"choice","ctx":"Жоғалған шешім. Дұрыс жауапты таңдаңыз.","q":"$y'=x(y^2-1)$ теңдеуінің $y=\\dfrac{1+Ce^{x^2}}{1-Ce^{x^2}}$ жалпы формуласына қай тұрақты шешім <em>кірмейді</em>?","o":["$y\\equiv1$","$y\\equiv-1$","$y\\equiv0$","барлық тұрақты шешім кіреді"],"a":1,"e":"$C=0$ болса, $y\\equiv1$. $y\\equiv-1$ ешбір шектік $C$-да алынбайды. $y\\equiv0$ теңдеудің шешімі емес ($0\\ne x\\cdot(-1)$)."},{"id":"m9-2-num-exp-diff:0","l":2,"lvl":"medium","type":"num","ctx":"Жасырын көбейтінді. Жауапты логарифмдік өрнек түрінде жазуға болады (мысалы, ln(4) не log(4)).","q":"$y'=e^{x-y}$, $y(0)=\\ln2$. $y(\\ln3)=\\ ?$","a":"log(4)"},{"id":"m9-2-expr-orth:0","l":2,"lvl":"hard","type":"expr","ctx":"Ортогональ траектория. Өрнекті $x,y$ арқылы жазыңыз.","q":"$y=Cx^2$ әулетінің ортогональ траекториясының еңісі $y'=\\ ?$ ($x,y$ арқылы)","vars":["x","y"],"dom":[0.5,3],"a":"-x/(2*y)"},{"id":"m9-2-num-logistic:0","l":2,"lvl":"hard","type":"num","ctx":"Логистикалық өсу. Жауапты ондық бөлшекпен жазыңыз (2 таңбаға дейін).","q":"$P'=0{,}5P\\big(1-\\tfrac{P}{200}\\big)$, $P(0)=50$. Популяция $100$ болатын $t$ қанша? ($\\ln3\\approx1{,}0986$)","a":"2*log(3)","tol":0.02},{"id":"m9-2-expr-logistic:0","l":2,"lvl":"hard","type":"expr","ctx":"Логистикалық шешімді жазу. Өрнекті $t$ арқылы жазыңыз.","q":"$P'=0{,}4P\\big(1-\\tfrac{P}{1000}\\big)$, $P(0)=100$. $P(t)=\\ ?$","vars":["t"],"dom":[0,8],"a":"1000/(1+9*exp(-0.4*t))"},{"id":"m9-2-tf-logistic:0","l":2,"lvl":"hard","type":"tf","ctx":"Логистикалық модель туралы. Әр пікірді бағалаңыз.","q":"$P_0>K$ болса, логистикалық теңдеудің шешімі $K$-ға жоғарыдан жақындайды.","a":true,"e":"Ақиқат: $P>K$ кезінде $1-P/K<0$, сондықтан $P'<0$, шешім кемиді, бірақ $K$ тепе-теңдігін қиып өтпейді."},{"id":"m9-2-tf-logistic:1","l":2,"lvl":"hard","type":"tf","ctx":"Логистикалық модель туралы. Әр пікірді бағалаңыз.","q":"Логистикалық шешімнің иілу нүктесі әрдайым $P=K$ деңгейінде болады.","a":false,"e":"Жалған: иілу нүктесі $P=K/2$ деңгейінде."},{"id":"m9-2-tf-logistic:2","l":2,"lvl":"hard","type":"tf","ctx":"Логистикалық модель туралы. Әр пікірді бағалаңыз.","q":"$P\\equiv0$ - логистикалық теңдеудің тепе-теңдік шешімі.","a":true,"e":"Ақиқат: $0=r\\cdot0\\cdot(1-0)$."},{"id":"m9-2-choice-hard:0","l":2,"lvl":"hard","type":"choice","ctx":"Тепе-теңдік пен мінез. Дұрыс жауапты таңдаңыз.","q":"$y'=y(y-3)$, $y(0)=1$. $x\\to+\\infty$ кезінде шешім қалай өзгереді?","o":["$3$-ке жақындайды","$0$-ге жақындайды","$-\\infty$-ке кетеді","тербеледі"],"a":1,"e":"$0<y<3$ аралығында $y(y-3)<0$, шешім кемиді. Төменнен $y\\equiv0$ тепе-теңдігі шектейді, сондықтан $y\\to0$."},{"id":"m9-2-num-half-t:0","l":2,"lvl":"hard","type":"num","ctx":"Дәл жартылай период. Жауапты санмен жазыңыз (ln 2 ≈ 0,6931).","q":"$y'=-0{,}2\\,y$. Жартылай ыдырау периоды (бір таңбаға дейін, ln 2 қолданыңыз)?","a":"5*log(2)","tol":0.05},{"id":"w56-q0","l":2,"lvl":"quiz","type":"choice","q":"Қай теңдеу айнымалылары бөлінетін теңдеу?","o":["y' = x + y","y' = x·e^y","y' = sin(x + y)","y' = x² + y²"],"a":1,"e":"x·e^y көбейтіндісінде бірінші көбейткіш тек x-ке, екіншісі тек y-ке тәуелді."},{"id":"w56-q1","l":2,"lvl":"quiz","type":"choice","q":"y' = 2y, y(0) = 5 шешімі:","o":["5e^(2x)","2e^(5x)","5 + 2x","e^(2x) + 5"],"a":0,"e":"y = Ce^(2x), y(0) = C = 5."},{"id":"w56-q2","l":2,"lvl":"quiz","type":"choice","q":"y' = y(y − 1) теңдеуінің тепе-теңдік шешімдері:","o":["y = 0 ғана","y = 1 ғана","y = 0 және y = 1","y = −1 және y = 1"],"a":2,"e":"Оң жағы y = 0 және y = 1 нүктелерінде нөл."},{"id":"w56-q3","l":2,"lvl":"quiz","type":"choice","q":"Заттың жартылай ыдырау периоды 6 сағат. 18 сағаттан кейін қанша үлесі қалады?","o":["1/2","1/4","1/8","1/16"],"a":2,"e":"18 = 3·6, үш период: (1/2)³ = 1/8."},{"id":"w56-q4","l":2,"lvl":"quiz","type":"choice","q":"Ньютонның суу заңында T(t) → ?","o":["0","T₀","Tₐ","∞"],"a":2,"e":"Дене орта температурасына Tₐ дейін суиды."},{"id":"w56-q5","l":2,"lvl":"quiz","type":"choice","q":"Логистикалық теңдеудің шешімі ең жылдам өсетін деңгей қандай?","o":["P = K","P = K/2","P = K/4","P = 0"],"a":1,"e":"P' = rP(1 − P/K) квадраттық функцияның төбесі P = K/2 нүктесінде."},{"id":"w56-q6","l":2,"lvl":"quiz","type":"choice","q":"y' = x/y, y(0) = 2 (y > 0) шешімі:","o":["y = x + 2","y = √(x² + 4)","y = e^x + 1","y = 2e^x"],"a":1,"e":"y dy = x dx ⇒ y² = x² + C, y(0) = 2 ⇒ C = 4."},{"id":"w56-q7","l":2,"lvl":"quiz","type":"choice","q":"y = Cx² әулетінің ортогональ траекториясының еңісі:","o":["2y/x","−2y/x","−x/(2y)","x/(2y)"],"a":2,"e":"Әулет еңісі 2y/x, ортогональ еңіс оның −1/k мәні: −x/(2y)."},{"id":"m9-3-tf-lin:0","l":3,"lvl":"easy","type":"tf","ctx":"Сызықтық теңдеу туралы. Әр пікірді бағалаңыз.","q":"$y'+x^2y=\\sin x$ теңдеуі бірінші ретті сызықтық теңдеу.","a":true,"e":"Ақиқат: $p=x^2$, $q=\\sin x$."},{"id":"m9-3-tf-lin:1","l":3,"lvl":"easy","type":"tf","ctx":"Сызықтық теңдеу туралы. Әр пікірді бағалаңыз.","q":"$y'+y^2=x$ теңдеуі сызықтық теңдеу.","a":false,"e":"Жалған: $y^2$ - сызықтық емес мүше."},{"id":"m9-3-tf-lin:2","l":3,"lvl":"easy","type":"tf","ctx":"Сызықтық теңдеу туралы. Әр пікірді бағалаңыз.","q":"Интегралдаушы көбейткіш $\\mu(x)=e^{\\int p\\,dx}$ ешқашан нөлге айналмайды.","a":true,"e":"Ақиқат: көрсеткіштік функция әрдайым оң."},{"id":"m9-3-tf-lin:3","l":3,"lvl":"easy","type":"tf","ctx":"Сызықтық теңдеу туралы. Әр пікірді бағалаңыз.","q":"$y'+py=q$ теңдеуінің екі шешімінің қосындысы да шешім болады ($q\\not\\equiv0$).","a":false,"e":"Жалған: қосындыда оң жағы $2q$ болады; тек айырма біртекті теңдеуді қанағаттандырады."},{"id":"m9-3-choice-std:0","l":3,"lvl":"easy","type":"choice","ctx":"Стандартты түрге келтіру. Дұрыс жауапты таңдаңыз.","q":"$x\\,y'+2y=x^3$ ($x>0$) теңдеуін $y'+p(x)y=q(x)$ түріне келтіргенде $p(x)=\\ ?$","o":["$2$","$\\dfrac2x$","$2x$","$\\dfrac{x}{2}$"],"a":1,"e":"$x$-ке бөлеміз: $y'+\\dfrac2x y=x^2$."},{"id":"m9-3-choice-std:1","l":3,"lvl":"easy","type":"choice","ctx":"Стандартты түрге келтіру. Дұрыс жауапты таңдаңыз.","q":"$y'-3y=e^{2x}$ теңдеуінің интегралдаушы көбейткіші:","o":["$e^{3x}$","$e^{-3x}$","$e^{2x}$","$e^{-2x}$"],"a":1,"e":"$p=-3$, $\\mu=e^{\\int(-3)dx}=e^{-3x}$."},{"id":"m9-3-num-first:0","l":3,"lvl":"easy","type":"num","ctx":"Қарапайым есеп. Жауапты санмен жазыңыз.","q":"$y'+y=2$, $y(0)=0$ шешімі $y=2(1-e^{-x})$. $y(\\ln2)=\\ ?$","a":1},{"id":"m9-3-num-first:1","l":3,"lvl":"easy","type":"num","ctx":"Қарапайым есеп. Жауапты санмен жазыңыз.","q":"$y'+3y=6$ үшін $x\\to\\infty$ кезінде $y$ неге ұмтылады?","a":2},{"id":"m9-3-expr-ivp1:0","l":3,"lvl":"medium","type":"expr","ctx":"Бастапқы есеп (1). Өрнекті $x$ арқылы жазыңыз.","q":"$y'+2y=e^{-x}$, $y(0)=3$. $y(x)=\\ ?$","a":"exp(-x)+2*exp(-2*x)"},{"id":"m9-3-expr-ivp2:0","l":3,"lvl":"medium","type":"expr","ctx":"Бастапқы есеп (2). Өрнекті $x$ арқылы жазыңыз ($x>0$).","q":"$xy'+y=x^3$, $y(1)=2$. $y(x)=\\ ?$","a":"x^3/4+7/(4*x)","dom":[0.5,4]},{"id":"m9-3-num-mix:0","l":3,"lvl":"medium","type":"num","ctx":"Қоспа есебі. Жауапты ондық бөлшекпен жазыңыз (бір таңбаға дейін).","q":"Көлемі $100$ л ыдыста бастапқыда $0$ кг тұз. Концентрациясы $0{,}2$ кг/л ерітінді $5$ л/мин жылдамдықпен құйылып, сол жылдамдықпен шығады. $x(t)=20(1-e^{-t/20})$. Тұз мөлшері $10$ кг болатын $t$ қанша? ($\\ln2\\approx0{,}693$)","a":"20*log(2)","tol":0.1},{"id":"m9-3-int-dom3:0","l":3,"lvl":"medium","type":"interval","ctx":"Шешім аралығы. Аралық түрінде жазыңыз; шексіздік - oo.","q":"$xy'+y=x^3$, $y(1)=2$ шешімі өмір сүретін ең үлкен аралық (коэффициент үзіліссіз болатын, бастапқы нүктені қамтитын).","a":"(0; oo)"},{"id":"m9-3-choice-struct:0","l":3,"lvl":"medium","type":"choice","ctx":"Шешім құрылымы. Дұрыс жауапты таңдаңыз.","q":"$y_1$ және $y_2$ - $y'+py=q$ ($q\\not\\equiv0$) теңдеуінің екі шешімі. Қай функция <em>біртекті</em> $y'+py=0$ теңдеуінің шешімі?","o":["$y_1+y_2$","$y_1-y_2$","$y_1\\cdot y_2$","$2y_1$"],"a":1,"e":"$(y_1-y_2)'+p(y_1-y_2)=q-q=0$. Қосындыда $2q$, $2y_1$ үшін $2q$ шығады."},{"id":"m9-3-expr-swap:0","l":3,"lvl":"hard","type":"expr","ctx":"x пен y-тің рөлін ауыстыру. Өрнекті $y$ арқылы жазыңыз.","q":"$\\dfrac{dx}{dy}=x+y$, $x(0)=1$ ($y=0$ кезінде $x=1$). $x(y)=\\ ?$","vars":["y"],"dom":[-2,2],"a":"2*exp(y)-y-1"},{"id":"m9-3-expr-cos:0","l":3,"lvl":"hard","type":"expr","ctx":"Тригонометриялық оң жақ. Өрнекті $x$ арқылы жазыңыз ($x>0$).","q":"$y'-\\dfrac2xy=x^2\\cos x$, $y(\\pi)=0$. $y(x)=\\ ?$","a":"x^2*sin(x)","dom":[0.5,4]},{"id":"m9-3-num-rl:0","l":3,"lvl":"hard","type":"num","ctx":"RL тізбегі. Жауапты ондық бөлшекпен жазыңыз (үш таңбаға дейін).","q":"$L=2$ Гн, $R=10$ Ом, $E=20$ В, $I(0)=0$. $I=1{,}5$ А болатын $t$ (секунд)? ($\\ln4\\approx1{,}3863$)","a":"log(4)/5","tol":0.001},{"id":"m9-3-tf-global:0","l":3,"lvl":"hard","type":"tf","ctx":"Шешім аралығы туралы. Әр пікірді бағалаңыз.","q":"$p,q$ үзіліссіз болатын $I$ аралығында сызықтық теңдеудің шешімі бүкіл $I$-де өмір сүреді.","a":true,"e":"Ақиқат (Теорема 3.1): формулада бөлгіш $\\mu>0$ нөлге айналмайды."},{"id":"m9-3-tf-global:1","l":3,"lvl":"hard","type":"tf","ctx":"Шешім аралығы туралы. Әр пікірді бағалаңыз.","q":"Интегралдаушы көбейткіш бірмәнді анықталады.","a":false,"e":"Жалған: $c\\mu(x)$ ($c\\ne0$) да интегралдаушы көбейткіш болады."},{"id":"m9-3-tf-global:2","l":3,"lvl":"hard","type":"tf","ctx":"Шешім аралығы туралы. Әр пікірді бағалаңыз.","q":"$q\\equiv0$ кезінде $y'+py=0$ теңдеуінің жалғыз шешімі $y\\equiv0$.","a":false,"e":"Жалған: $y=Ce^{-\\int p}$ барлық шешім; $y\\equiv0$ - тек $C=0$ жағдайы."},{"id":"m9-3-choice-sin:0","l":3,"lvl":"hard","type":"choice","ctx":"Тұрақты күй және өтпелі бөлік. Дұрыс пікірлерді белгілеңіз.","q":"$y'+y=\\sin x$, $y(0)=0$ шешімі $y=\\dfrac{\\sin x-\\cos x+e^{-x}}{2}$. Қай пікірлер ақиқат?","o":["Өтпелі бөлік - $\\dfrac{e^{-x}}2$","Тұрақты күй - $\\dfrac{\\sin x-\\cos x}2$ (тербелмелі)","$x\\to\\infty$ кезінде $y\\to0$","$y(0)=0$ шарты орындалады"],"a":[0,1,3],"e":"$e^{-x}/2\\to0$ өтпелі. $(\\sin x-\\cos x)/2$ тербеледі, нөлге ұмтылмайды. $y(0)=(0-1+1)/2=0$."},{"id":"m9-3-num-sin:0","l":3,"lvl":"hard","type":"num","ctx":"Тербелмелі оң жақ. Жауапты ондық бөлшекпен жазыңыз (үш таңбаға дейін).","q":"$y'+y=\\sin x$, $y(0)=0$. $y(\\pi)=\\ ?$ ($e^{-\\pi}\\approx0{,}0432$)","a":"(1+exp(-pi))/2","tol":0.001},{"id":"w57-q0","l":3,"lvl":"quiz","type":"choice","q":"y' + 4y = 8 теңдеуінің тұрақты күйі (x → ∞ кезіндегі шек) қандай?","o":["4","8","2","0"],"a":2,"e":"y' = 0 болса, 4y = 8, y = 2."},{"id":"w57-q1","l":3,"lvl":"quiz","type":"choice","q":"y' − 2y = x теңдеуінің интегралдаушы көбейткіші:","o":["e^(2x)","e^(−2x)","x","e^x"],"a":1,"e":"p = −2, μ = e^(−2x)."},{"id":"w57-q2","l":3,"lvl":"quiz","type":"choice","q":"x·y' + 3y = x² (x > 0) теңдеуінде p(x) қандай?","o":["3","3x","3/x","x/3"],"a":2,"e":"x-ке бөлсек, y' + (3/x)y = x."},{"id":"w57-q3","l":3,"lvl":"quiz","type":"choice","q":"y' + y = e^(−x), y(0) = 1 шешімі:","o":["e^(−x)(x + 1)","e^(−x)","e^x + x","x·e^(−x)"],"a":0,"e":"μ = e^x, (e^x y)' = 1 ⇒ e^x y = x + C, C = 1."},{"id":"w57-q4","l":3,"lvl":"quiz","type":"choice","q":"Қоспа есебінде x' = 2 − x/50 теңдеуінің тұрақты күйі қандай?","o":["50","100","2","25"],"a":1,"e":"x' = 0 ⇒ x = 100."},{"id":"w57-q5","l":3,"lvl":"quiz","type":"choice","q":"RL тізбегінің уақыт тұрақтысы τ неге тең?","o":["R/L","L/R","L·R","E/R"],"a":1,"e":"Ток e^(−Rt/L) бойынша жақындайды, τ = L/R."},{"id":"w57-q6","l":3,"lvl":"quiz","type":"choice","q":"Біртекті емес теңдеудің екі шешімінің айырмасы:","o":["біртекті теңдеуді қанағаттандырады","әрдайым нөл","сызықтық емес теңдеуді қанағаттандырады","біртекті емес теңдеудің шешімі"],"a":0,"e":"(y₁ − y₂)' + p(y₁ − y₂) = q − q = 0."},{"id":"w57-q7","l":3,"lvl":"quiz","type":"choice","q":"dx/dy = x + y теңдеуінің жалпы шешімі:","o":["x = Ce^y − y − 1","x = Ce^y + y + 1","x = Ce^(−y) − y","x = y² + C"],"a":0,"e":"x' − x = y, μ = e^(−y), x = −y − 1 + Ce^y."},{"id":"m9-4-tf-exact:0","l":4,"lvl":"easy","type":"tf","ctx":"Дәл теңдеу туралы. Әр пікірді бағалаңыз.","q":"$(2x+y)dx+(x+3y^2)dy=0$ теңдеуі дәл дифференциалды.","a":true,"e":"Ақиқат: $M_y=1$, $N_x=1$."},{"id":"m9-4-tf-exact:1","l":4,"lvl":"easy","type":"tf","ctx":"Дәл теңдеу туралы. Әр пікірді бағалаңыз.","q":"$y\\,dx-x\\,dy=0$ теңдеуі дәл дифференциалды.","a":false,"e":"Жалған: $M_y=1$, $N_x=-1$."},{"id":"m9-4-tf-exact:2","l":4,"lvl":"easy","type":"tf","ctx":"Дәл теңдеу туралы. Әр пікірді бағалаңыз.","q":"Дәл теңдеудің шешімі $F(x,y)=C$ түрінде жазылады, мұнда $F_x=M$, $F_y=N$.","a":true,"e":"Ақиқат: $dF=0$ ⇒ $F=C$."},{"id":"m9-4-tf-exact:3","l":4,"lvl":"easy","type":"tf","ctx":"Дәл теңдеу туралы. Әр пікірді бағалаңыз.","q":"Бернулли теңдеуі $y'+py=qy^n$ әрдайым сызықтық теңдеу.","a":false,"e":"Жалған: $n\\ne0,1$ болса, ол сызықтық емес; тек $z=y^{1-n}$ ауыстыруымен сызықтыққа келеді."},{"id":"m9-4-choice-exact:0","l":4,"lvl":"easy","type":"choice","ctx":"Дәл теңдеуді тану. Дұрыс жауапты таңдаңыз.","q":"Қайсысы дәл дифференциалды теңдеу?","o":["$(x+y)dx+(x-y)dy=0$","$y\\,dx+2x\\,dy=0$","$x\\,dx+y^2dy+y\\,dx=0$","$y^2dx+x\\,dy=0$"],"a":0,"e":"1-нұсқада $M_y=1=N_x$. 2-нұсқада $M_y=1$, $N_x=2$; 3-те $M=x+y$, $N=y^2$: $M_y=1$, $N_x=0$; 4-те $M_y=2y$, $N_x=1$."},{"id":"m9-4-num-potential:0","l":4,"lvl":"easy","type":"num","ctx":"Потенциалдың мәні. Жауапты санмен жазыңыз.","q":"$(2x+y)dx+(x+3y^2)dy=0$ дәл. Потенциалы $F(0;0)=0$ болатындай алынса, $F(1;1)=\\ ?$","a":3},{"id":"m9-4-expr-potential:0","l":4,"lvl":"medium","type":"expr","ctx":"Потенциалды табу. $F(0;0)=0$ болатын потенциалды $x$, $y$ арқылы жазыңыз.","q":"$(2xy+3x^2)dx+(x^2+2y)dy=0$ дәл теңдеуінің потенциалы $F(x,y)=\\ ?$ ($F(0;0)=0$)","vars":["x","y"],"dom":[-2,2],"a":"x^2*y+x^3+y^2"},{"id":"m9-4-expr-bern:0","l":4,"lvl":"medium","type":"expr","ctx":"Бернулли ауыстыруынан кейінгі теңдеу. Оң жақты $x$, $z$ арқылы жазыңыз.","q":"$y'+\\dfrac yx=xy^2$ теңдеуінде $z=\\dfrac1y$ ауыстыруынан кейін $z'=\\ ?$ ($x$ және $z$ арқылы)","vars":["x","z"],"dom":[0.5,3],"a":"-x+z/x"},{"id":"m9-4-num-homog:0","l":4,"lvl":"medium","type":"num","ctx":"Біртекті теңдеудің шешімі. Жауапты санмен жазыңыз.","q":"$y'=\\dfrac{x^2+y^2}{xy}$, $y(1)=2$ шешімі $y^2=x^2(2\\ln x+4)$. $x=e$ болғанда $\\dfrac{y^2}{x^2}=\\ ?$","a":6},{"id":"m9-4-num-k:0","l":4,"lvl":"medium","type":"num","ctx":"Параметрді табу. Жауапты санмен жазыңыз.","q":"$(2xy+ky^2)dx+(x^2+4xy)dy=0$ теңдеуі дәл болатын $k=\\ ?$","a":2},{"id":"m9-4-choice-sub:0","l":4,"lvl":"medium","type":"choice","ctx":"Ауыстыруды таңдау. Дұрыс жауапты таңдаңыз.","q":"$y'+\\dfrac{y}{x}=x\\,y^3$ теңдеуін сызықтыққа келтіру үшін қай ауыстыру керек?","o":["$z=y^3$","$z=y^{-2}$","$z=\\dfrac yx$","$z=y^{2}$"],"a":1,"e":"$n=3$, $z=y^{1-n}=y^{-2}$."},{"id":"m9-4-num-bern:0","l":4,"lvl":"hard","type":"num","ctx":"Бернулли есебі. Жауапты ондық бөлшекпен жазыңыз.","q":"$y'+\\dfrac yx=xy^2$, $y(1)=\\dfrac12$ шешімі $y=\\dfrac1{x(3-x)}$. $y\\!\\left(\\tfrac12\\right)=\\ ?$","a":0.8},{"id":"m9-4-expr-mu:0","l":4,"lvl":"hard","type":"expr","ctx":"Интегралдаушы көбейткіш. $x$ арқылы жазыңыз ($x>0$).","q":"$(3xy+y^2)dx+(x^2+xy)dy=0$ үшін тек $x$-ке тәуелді интегралдаушы көбейткіш $\\mu(x)=\\ ?$ ($\\mu(1)=1$ деп алыңыз)","a":"x","dom":[0.5,4]},{"id":"m9-4-expr-phi:0","l":4,"lvl":"hard","type":"expr","ctx":"Біртекті теңдеудегі v-ның теңдеуі. $v$ арқылы жазыңыз.","q":"$y'=\\dfrac{x^2+y^2}{xy}$ теңдеуінде $y=vx$ ауыстырсақ, $x\\,v'=\\ ?$ ($v$ арқылы)","vars":["v"],"dom":[0.5,3],"a":"1/v"},{"id":"m9-4-tf-hard4:0","l":4,"lvl":"hard","type":"tf","ctx":"Түрін тану. Әр пікірді бағалаңыз.","q":"$y'=\\dfrac{y}{x}+\\sin\\dfrac yx$ теңдеуі біртекті.","a":true,"e":"Ақиқат: оң жағы тек $y/x$-тің функциясы."},{"id":"m9-4-tf-hard4:1","l":4,"lvl":"hard","type":"tf","ctx":"Түрін тану. Әр пікірді бағалаңыз.","q":"$y'=x+y^2$ теңдеуі біртекті.","a":false,"e":"Жалған: $f(tx,ty)=tx+t^2y^2\\ne f(x,y)$."},{"id":"m9-4-tf-hard4:2","l":4,"lvl":"hard","type":"tf","ctx":"Түрін тану. Әр пікірді бағалаңыз.","q":"Бернулли теңдеуінде $n=0$ болса, ол сызықтық теңдеу.","a":true,"e":"Ақиқат: $y'+py=q$."},{"id":"m9-4-mat-grad:0","l":4,"lvl":"hard","type":"matrix","ctx":"Потенциалдың дербес туындылары. Векторды баған түрінде жазыңыз.","q":"$F=x^2y+2xy^2$. $(1;1)$ нүктесінде $\\begin{pmatrix}F_x\\\\F_y\\end{pmatrix}$ векторын табыңыз.","name":"$\\nabla F=$","a":[[4],[5]]},{"id":"m9-4-choice-homog:0","l":4,"lvl":"hard","type":"choice","ctx":"Біртекті функциялар. Нөл дәрежелі біртекті функцияларды белгілеңіз.","q":"Қайсысы нөл дәрежелі біртекті функция (тек $x\\ne0$, $y\\ne0$ үшін)?","o":["$\\dfrac{x-y}{x+y}$","$\\dfrac{x^2+y}{x}$","$\\ln\\dfrac yx$","$\\sqrt{x^2+y^2}$"],"a":[0,2],"e":"$\\dfrac{tx-ty}{tx+ty}$ және $\\ln\\dfrac{ty}{tx}$ $t$-ға тәуелсіз. $\\dfrac{x^2+y}{x}$ біртекті емес, $\\sqrt{x^2+y^2}$ - 1 дәрежелі."},{"id":"w58-q0","l":4,"lvl":"quiz","type":"choice","q":"(y + 2x)dx + (x + 3y²)dy = 0 теңдеуі үшін қай пікір ақиқат?","o":["дәл емес","дәл, потенциал xy + x² + y³","дәл, потенциал xy + y³","дәл, потенциал x² + y³"],"a":1,"e":"M_y = 1 = N_x. F = xy + x² + y³."},{"id":"w58-q1","l":4,"lvl":"quiz","type":"choice","q":"y dx − x dy = 0 теңдеуін дәл ету үшін қандай көбейткішке көбейтуге болады?","o":["1/x²","x","y","1"],"a":0,"e":"1/x² көбейткенде y/x² dx − 1/x dy: M_y = 1/x², N_x = 1/x²."},{"id":"w58-q2","l":4,"lvl":"quiz","type":"choice","q":"y' + y = y² (Бернулли) теңдеуінде қандай ауыстыру сызықтыққа келтіреді?","o":["z = y²","z = 1/y","z = y/x","z = ln y"],"a":1,"e":"n = 2, z = y^(1−n) = 1/y."},{"id":"w58-q3","l":4,"lvl":"quiz","type":"choice","q":"y' = (x + y)/x теңдеуі қай түрге жатады?","o":["тек Бернулли","біртекті және сызықтық","дәл емес және бөлінбейді","тек бөлінетін"],"a":1,"e":"Оң жағы 1 + y/x: біртекті; сондай-ақ y' − y/x = 1 сызықтық."},{"id":"w58-q4","l":4,"lvl":"quiz","type":"choice","q":"Біртекті теңдеуде y = vx қойғанда y' неге тең?","o":["v'x","v'x + v","v' + x","v"],"a":1,"e":"Көбейтіндінің туындысы: (vx)' = v'x + v."},{"id":"w58-q5","l":4,"lvl":"quiz","type":"choice","q":"(x² + y²)dx + 2xy dy = 0 теңдеуі дәл ме?","o":["иә","жоқ","тек x > 0 кезінде","тек y > 0 кезінде"],"a":0,"e":"M_y = 2y, N_x = 2y: тең, дәл. Потенциал x³/3 + xy²."},{"id":"w58-q6","l":4,"lvl":"quiz","type":"choice","q":"Дәл теңдеудің жалпы шешімі қалай жазылады?","o":["F(x, y) = C","y = F(x)","M = N","F_x = F_y"],"a":0,"e":"dF = 0 болғандықтан F(x, y) = C."},{"id":"w58-q7","l":4,"lvl":"quiz","type":"choice","q":"y' + y/x = xy² теңдеуінде z = 1/y болса, z' + ... теңдеуі:","o":["z' − z/x = −x","z' + z/x = x","z' − z/x = x","z' + z/x = −x"],"a":0,"e":"z' = −y'/y² = −x + z/x ⇒ z' − z/x = −x."},{"id":"m9-5-tf-char:0","l":5,"lvl":"easy","type":"tf","ctx":"Сипаттамалық теңдеу туралы. Әр пікірді бағалаңыз.","q":"$y''-5y'+6y=0$ теңдеуінің сипаттамалық теңдеуі $r^2-5r+6=0$.","a":true,"e":"Ақиқат: $y''\\to r^2$, $y'\\to r$, $y\\to1$."},{"id":"m9-5-tf-char:1","l":5,"lvl":"easy","type":"tf","ctx":"Сипаттамалық теңдеу туралы. Әр пікірді бағалаңыз.","q":"$y''+9y=0$ шешімдері $e^{3x}$ және $e^{-3x}$.","a":false,"e":"Жалған: $r^2=-9$, $r=\\pm3i$, шешімдер $\\cos3x$, $\\sin3x$."},{"id":"m9-5-tf-char:2","l":5,"lvl":"easy","type":"tf","ctx":"Сипаттамалық теңдеу туралы. Әр пікірді бағалаңыз.","q":"$D=0$ болса, екінші шешім $xe^{rx}$.","a":true,"e":"Ақиқат (4-қорыту)."},{"id":"m9-5-tf-char:3","l":5,"lvl":"easy","type":"tf","ctx":"Сипаттамалық теңдеу туралы. Әр пікірді бағалаңыз.","q":"$y_1$ және $3y_1$ екеуі шешім болса, олардың қосындысы жалпы шешім береді.","a":false,"e":"Жалған: олар сызықтық тәуелді, $W=0$."},{"id":"m9-5-choice-D:0","l":5,"lvl":"easy","type":"choice","ctx":"Дискриминант бойынша түрі. Дұрыс жауапты таңдаңыз.","q":"$y''+4y'+4y=0$ теңдеуінің жалпы шешімі:","o":["$C_1e^{2x}+C_2e^{-2x}$","$(C_1+C_2x)e^{-2x}$","$e^{-2x}(C_1\\cos2x+C_2\\sin2x)$","$C_1e^{-2x}+C_2e^{-4x}$"],"a":1,"e":"$(r+2)^2=0$, $r=-2$ екі еселі."},{"id":"m9-5-choice-D:1","l":5,"lvl":"easy","type":"choice","ctx":"Дискриминант бойынша түрі. Дұрыс жауапты таңдаңыз.","q":"$y''+2y'+10y=0$ шешімінің $\\cos$/$\\sin$ жиілігі $\\beta=\\ ?$","o":["1","2","3","10"],"a":2,"e":"$r=-1\\pm3i$."},{"id":"m9-5-num-disc:0","l":5,"lvl":"easy","type":"num","ctx":"Дискриминант. Жауапты санмен жазыңыз.","q":"$y''-3y'+2y=0$ үшін $D=b^2-4ac=\\ ?$","a":1},{"id":"m9-5-num-disc:1","l":5,"lvl":"easy","type":"num","ctx":"Дискриминант. Жауапты санмен жазыңыз.","q":"$y''+2y'+5y=0$ үшін $D=\\ ?$","a":-16},{"id":"m9-5-expr-real:0","l":5,"lvl":"medium","type":"expr","ctx":"Нақты түбірлер: бастапқы есеп. Өрнекті $x$ арқылы жазыңыз.","q":"$y''-3y'+2y=0$, $y(0)=1$, $y'(0)=0$. $y(x)=\\ ?$","a":"2*exp(x)-exp(2*x)"},{"id":"m9-5-expr-complex:0","l":5,"lvl":"medium","type":"expr","ctx":"Комплекс түбірлер: бастапқы есеп. Өрнекті $x$ арқылы жазыңыз.","q":"$y''+4y=0$, $y(0)=0$, $y'(0)=2$. $y(x)=\\ ?$","a":"sin(2*x)"},{"id":"m9-5-expr-double:0","l":5,"lvl":"medium","type":"expr","ctx":"Еселі түбір: бастапқы есеп. Өрнекті $x$ арқылы жазыңыз.","q":"$y''+6y'+9y=0$, $y(0)=2$, $y'(0)=-1$. $y(x)=\\ ?$","a":"(2+5*x)*exp(-3*x)"},{"id":"m9-5-num-wr:0","l":5,"lvl":"medium","type":"num","ctx":"Вронскиан. Жауапты санмен жазыңыз.","q":"$y_1=e^{2x}$, $y_2=e^{-x}$. $W(y_1,y_2)(0)=\\ ?$","a":-3},{"id":"m9-5-num-wr:1","l":5,"lvl":"medium","type":"num","ctx":"Вронскиан. Жауапты санмен жазыңыз.","q":"$y_1=\\cos2x$, $y_2=\\sin2x$. $W(y_1,y_2)(x)=\\ ?$","a":2},{"id":"m9-5-int-k:0","l":5,"lvl":"medium","type":"interval","ctx":"Тербеліс шарты. Аралық түрінде жазыңыз.","q":"$y''+ky'+4y=0$ шешімі тербелетін $k$ мәндерінің жиыны.","a":"(-4; 4)"},{"id":"m9-5-num-ode-c:0","l":5,"lvl":"medium","type":"num","ctx":"Теңдеуді құру. Жауапты санмен жазыңыз.","q":"Сипаттамалық түбірлері $2$ және $-3$ болатын $y''+y'+cy=0$ теңдеуіндегі $c=\\ ?$","a":-6},{"id":"m9-5-mat-roots:0","l":5,"lvl":"hard","type":"matrix","ctx":"Түбірлер векторы. Түбірлерді өсу ретімен баған түрінде жазыңыз.","q":"$y''-5y'+6y=0$ теңдеуінің сипаттамалық түбірлері $\\begin{pmatrix}r_1\\\\r_2\\end{pmatrix}$ ($r_1<r_2$).","name":"$r=$","a":[[2],[3]]},{"id":"m9-5-num-abel:0","l":5,"lvl":"hard","type":"num","ctx":"Абель формуласы. Жауапты ондық бөлшекпен жазыңыз.","q":"$y''+2y'+5y=0$ шешімдерінің Вронскианы үшін $W(0)=1$. $W(1)=\\ ?$ (ондық бөлшекпен, $e^{-2}\\approx0{,}1353$)","a":"exp(-2)","tol":0.001},{"id":"m9-5-choice-crit:0","l":5,"lvl":"hard","type":"choice","ctx":"Демпфирлеу режимі. Дұрыс жауапты таңдаңыз.","q":"$y''+cy'+25y=0$. Критикалық режим (тербеліссіз ең жылдам өшу) үшін $c=\\ ?$ ($c>0$)","o":["5","10","20","25"],"a":1,"e":"$D=c^2-100=0$, $c=10$; $c<10$ - өшетін тербеліс, $c>10$ - тербеліссіз баяу өшу."},{"id":"m9-5-tf-wr:0","l":5,"lvl":"hard","type":"tf","ctx":"Вронскиан туралы. Әр пікірді бағалаңыз.","q":"Біртекті $y''+py'+qy=0$ теңдеуінің екі шешімінің Вронскианы бір нүктеде нөл болса, ол барлық нүктеде нөл.","a":true,"e":"Ақиқат: Абель формуласы, $W=W(x_0)e^{-\\int p}$."},{"id":"m9-5-tf-wr:1","l":5,"lvl":"hard","type":"tf","ctx":"Вронскиан туралы. Әр пікірді бағалаңыз.","q":"Кез келген екі функцияның Вронскианы нөл болса, олар сызықтық тәуелді.","a":false,"e":"Жалған: жалпы функциялар үшін болмайды (мысалы, $x^2$ және $x|x|$: $W\\equiv0$, бірақ тәуелсіз). Шешімдер үшін ғана дұрыс."},{"id":"m9-5-tf-wr:2","l":5,"lvl":"hard","type":"tf","ctx":"Вронскиан туралы. Әр пікірді бағалаңыз.","q":"$y''+y=0$ шешімдерінің жалпы шешімінде $C_1\\cos x+C_2\\sin x=A\\cos(x-\\varphi)$.","a":true,"e":"Ақиқат: амплитудалық түр, $A=\\sqrt{C_1^2+C_2^2}$."},{"id":"m9-5-expr-gen:0","l":5,"lvl":"hard","type":"expr","ctx":"Жалпы шешімнің бір мүшесі. Өрнекті $x$ арқылы жазыңыз.","q":"$y''-2y'+5y=0$, $y(0)=0$, $y'(0)=2$. $y(x)=\\ ?$","a":"exp(x)*sin(2*x)"},{"id":"m9-5-num-env:0","l":5,"lvl":"hard","type":"num","ctx":"Тербелістің жиілігі мен периоды. Жауапты ондық бөлшекпен жазыңыз.","q":"$y''+0{,}2y'+9{,}01y=0$ тербелісінің бұрыштық жиілігі $\\beta=\\dfrac{\\sqrt{4ac-b^2}}{2a}$ неге тең?","a":3},{"id":"w59-q0","l":5,"lvl":"quiz","type":"choice","q":"y'' − 4y = 0 теңдеуінің жалпы шешімі:","o":["C₁cos2x + C₂sin2x","C₁e^(2x) + C₂e^(−2x)","(C₁ + C₂x)e^(2x)","C₁e^(4x) + C₂"],"a":1,"e":"r² = 4, r = ±2."},{"id":"w59-q1","l":5,"lvl":"quiz","type":"choice","q":"y'' + 4y = 0 теңдеуінің жалпы шешімі:","o":["C₁e^(2x) + C₂e^(−2x)","C₁cos2x + C₂sin2x","(C₁ + C₂x)e^(−2x)","C₁cos4x + C₂sin4x"],"a":1,"e":"r² = −4, r = ±2i."},{"id":"w59-q2","l":5,"lvl":"quiz","type":"choice","q":"y'' − 6y' + 9y = 0 теңдеуінің жалпы шешімі:","o":["C₁e^(3x) + C₂e^(−3x)","(C₁ + C₂x)e^(3x)","e^(3x)(C₁cosx + C₂sinx)","C₁e^(3x) + C₂e^(6x)"],"a":1,"e":"(r − 3)² = 0, r = 3 екі еселі."},{"id":"w59-q3","l":5,"lvl":"quiz","type":"choice","q":"y'' + 2y' + 10y = 0 теңдеуінің шешімінде амплитуда қалай өзгереді?","o":["өседі","өшеді","тұрақты","нөл"],"a":1,"e":"r = −1 ± 3i, нақты бөлік −1 < 0: e^(−x) бойынша өшеді."},{"id":"w59-q4","l":5,"lvl":"quiz","type":"choice","q":"e^(2x) және e^(−x) функцияларының Вронскианы:","o":["3e^x","−3e^x","0","e^x"],"a":1,"e":"W = e^(2x)(−e^(−x)) − 2e^(2x)e^(−x) = −3e^x."},{"id":"w59-q5","l":5,"lvl":"quiz","type":"choice","q":"Түбірлері 1 және −2 болатын теңдеу:","o":["y'' + y' − 2y = 0","y'' − y' − 2y = 0","y'' + 3y' + 2y = 0","y'' − 3y' + 2y = 0"],"a":0,"e":"(r − 1)(r + 2) = r² + r − 2."},{"id":"w59-q6","l":5,"lvl":"quiz","type":"choice","q":"y'' + ky' + 9y = 0 теңдеуінде критикалық демпфирлеу (k > 0) қашан болады?","o":["k = 3","k = 6","k = 9","k = 18"],"a":1,"e":"D = k² − 36 = 0, k = 6."},{"id":"w59-q7","l":5,"lvl":"quiz","type":"choice","q":"Екінші ретті біртекті сызықтық теңдеудің жалпы шешімінде қанша тәуелсіз тұрақты бар?","o":["1","2","3","шексіз"],"a":1,"e":"Шешімдер кеңістігінің өлшемі теңдеудің ретіне тең: 2."},{"id":"m9-6-tf-struct:0","l":6,"lvl":"easy","type":"tf","ctx":"Құрылым туралы. Әр пікірді бағалаңыз.","q":"Біртекті емес теңдеудің жалпы шешімі $y_h+y_p$ түрінде жазылады.","a":true,"e":"Ақиқат (Теорема 6.1)."},{"id":"m9-6-tf-struct:1","l":6,"lvl":"easy","type":"tf","ctx":"Құрылым туралы. Әр пікірді бағалаңыз.","q":"$y_p$-ны табу үшін бастапқы шарттарды қолдану керек.","a":false,"e":"Жалған: $y_p$ - кез келген бір дербес шешім, бастапқы шарттар соңында толық $y$ үшін қойылады."},{"id":"m9-6-tf-struct:2","l":6,"lvl":"easy","type":"tf","ctx":"Құрылым туралы. Әр пікірді бағалаңыз.","q":"$L[y_1]=f_1$, $L[y_2]=f_2$ болса, $L[y_1+y_2]=f_1+f_2$.","a":true,"e":"Ақиқат: оператор сызықтық."},{"id":"m9-6-tf-struct:3","l":6,"lvl":"easy","type":"tf","ctx":"Құрылым туралы. Әр пікірді бағалаңыз.","q":"$f=e^{x}$ болса және $r=1$ сипаттамалық түбір болса, $y_p=Ae^{x}$ жеткілікті.","a":false,"e":"Жалған: резонанс, $y_p=Axe^{x}$."},{"id":"m9-6-choice-trial:0","l":6,"lvl":"easy","type":"choice","ctx":"Дербес шешімнің түрін таңдау. Дұрыс түрді таңдаңыз.","q":"$y''-3y'+2y=x^2$ үшін $y_p$ түрі:","o":["$Ax^2$","$Ax^2+Bx+C$","$(Ax^2+Bx+C)e^{x}$","$Ax^3$"],"a":1,"e":"$0$ түбір емес ($p(0)=2$), $f$ - екінші дәрежелі көпмүшелік."},{"id":"m9-6-choice-trial:1","l":6,"lvl":"easy","type":"choice","ctx":"Дербес шешімнің түрін таңдау. Дұрыс түрді таңдаңыз.","q":"$y''+y=\\sin x$ үшін $y_p$ түрі:","o":["$A\\sin x$","$A\\cos x+B\\sin x$","$x(A\\cos x+B\\sin x)$","$Ax\\sin x$"],"a":2,"e":"$\\pm i$ - сипаттамалық түбір: резонанс, $s=1$."},{"id":"m9-6-num-const:0","l":6,"lvl":"easy","type":"num","ctx":"Тұрақты оң жақ. Жауапты санмен жазыңыз.","q":"$y''+3y=6$ теңдеуінің тұрақты дербес шешімі $y_p=\\ ?$","a":2},{"id":"m9-6-num-const:1","l":6,"lvl":"easy","type":"num","ctx":"Тұрақты оң жақ. Жауапты санмен жазыңыз.","q":"$y''+y'-2y=-8$ теңдеуінің тұрақты дербес шешімі?","a":4},{"id":"m9-6-expr-poly:0","l":6,"lvl":"medium","type":"expr","ctx":"Көпмүшелік дербес шешім. Өрнекті $x$ арқылы жазыңыз.","q":"$y''-3y'+2y=4x+1$ теңдеуінің дербес шешімі $y_p=\\ ?$ (көпмүшелік)","a":"2*x+7/2"},{"id":"m9-6-num-resA:0","l":6,"lvl":"medium","type":"num","ctx":"Резонанс коэффициенті. Жауапты санмен жазыңыз.","q":"$y''-3y'+2y=e^{x}$ үшін $y_p=Axe^{x}$ болса, $A=\\ ?$","a":-1},{"id":"m9-6-expr-trig:0","l":6,"lvl":"medium","type":"expr","ctx":"Тригонометриялық дербес шешім. Өрнекті $x$ арқылы жазыңыз.","q":"$y''+2y'+5y=\\cos2x$ үшін $y_p=\\ ?$","a":"(cos(2*x)+4*sin(2*x))/17"},{"id":"m9-6-expr-uprime:0","l":6,"lvl":"medium","type":"expr","ctx":"Вариация әдісі: u₁′. Өрнекті $x$ арқылы жазыңыз ($-\\pi/2<x<\\pi/2$).","q":"$y''+y=\\sec x$, $y_1=\\cos x$, $y_2=\\sin x$, $W=1$. $u_1'(x)=\\ ?$","a":"-tan(x)","dom":[-1,1]},{"id":"m9-6-choice-res:0","l":6,"lvl":"medium","type":"choice","ctx":"Резонанс па?. Дұрыс жауапты таңдаңыз.","q":"Қай теңдеуде резонанс болады?","o":["$y''+4y=\\cos3t$","$y''+4y=\\cos2t$","$y''+4y'+5y=\\cos2t$","$y''-4y=\\cos2t$"],"a":1,"e":"Тек $y''+4y=\\cos2t$ үшін $\\pm2i$ - сипаттамалық түбір. Үшіншіде үйкеліс бар (түбірлер $-2\\pm i$)."},{"id":"m9-6-expr-res:0","l":6,"lvl":"hard","type":"expr","ctx":"Резонанстық дербес шешім. Өрнекті $t$ арқылы жазыңыз.","q":"$y''+4y=\\cos2t$ үшін $y_p=\\ ?$ (бастапқы шарттары $y(0)=y'(0)=0$ болатын)","vars":["t"],"dom":[0,4],"a":"t*sin(2*t)/4"},{"id":"m9-6-expr-full:0","l":6,"lvl":"hard","type":"expr","ctx":"Толық шешім. Өрнекті $x$ арқылы жазыңыз.","q":"$y''-3y'+2y=4x+1$, $y(0)=0$, $y'(0)=1$. $y(x)=\\ ?$","a":"-6*exp(x)+5*exp(2*x)/2+2*x+7/2"},{"id":"m9-6-num-beat:0","l":6,"lvl":"hard","type":"num","ctx":"Резонанстағы мән. Жауапты өрнек түрінде жазуға болады (мысалы, pi/16).","q":"$y''+4y=\\cos2t$, $y(0)=y'(0)=0$ шешімі $y=\\dfrac t4\\sin2t$. $y\\!\\left(\\dfrac\\pi4\\right)=\\ ?$","a":"pi/16"},{"id":"m9-6-tf-res2:0","l":6,"lvl":"hard","type":"tf","ctx":"Резонанс туралы. Әр пікірді бағалаңыз.","q":"Үйкеліссіз жүйеде ($y''+\\omega^2y=\\cos\\omega t$) амплитуда уақытпен сызықты өседі.","a":true,"e":"Ақиқат: $y=t\\sin\\omega t/(2\\omega)$."},{"id":"m9-6-tf-res2:1","l":6,"lvl":"hard","type":"tf","ctx":"Резонанс туралы. Әр пікірді бағалаңыз.","q":"Үйкелісі бар жүйеде ($y''+by'+cy=\\cos\\beta t$, $b>0$) амплитуда шектеусіз өсуі мүмкін.","a":false,"e":"Жалған: $p(i\\beta)\\ne0$ ($b>0$), амплитуда $1/|p(i\\beta)|$ шекті."},{"id":"m9-6-tf-res2:2","l":6,"lvl":"hard","type":"tf","ctx":"Резонанс туралы. Әр пікірді бағалаңыз.","q":"Соғуда амплитуданың баяу өзгеру периоды $|\\omega-\\Omega|$ кішірейген сайын ұзарады.","a":true,"e":"Ақиқат: конверт периоды $4\\pi/|\\omega-\\Omega|$."},{"id":"m9-6-mat-AB:0","l":6,"lvl":"hard","type":"matrix","ctx":"Коэффициенттер векторы. Бөлшекті 1/17 түрінде жазуға болады.","q":"$y''+2y'+5y=\\cos2x$ үшін $y_p=A\\cos2x+B\\sin2x$. $\\begin{pmatrix}A\\\\B\\end{pmatrix}=\\ ?$","name":"$(A;B)=$","a":[["1/17"],["4/17"]]},{"id":"m9-6-choice-multi:0","l":6,"lvl":"hard","type":"choice","ctx":"Резонанстық түрлер. Дұрыс түрді таңдаңыз.","q":"$y''-3y'+2y=xe^{x}$ үшін $y_p$ түрі (түбірлер $1$ және $2$):","o":["$(Ax+B)e^{x}$","$(Ax^2+Bx)e^{x}$","$(Ax^2+Bx+C)e^{x}$","$(Ax+B)xe^{2x}$"],"a":1,"e":"$\\alpha=1$ жай түбір ($s=1$), $f$ - бірінші дәрежелі көпмүшелік: $x(Ax+B)e^{x}$."},{"id":"m9-6-num-amp:0","l":6,"lvl":"hard","type":"num","ctx":"Тұрақты күйдің амплитудасы. Жауапты өрнек түрінде жазуға болады (мысалы, 1/sqrt(17)).","q":"$y''+2y'+5y=\\cos2x$ тұрақты күйінің амплитудасы $\\dfrac{1}{|p(2i)|}=\\ ?$","a":"1/sqrt(17)"},{"id":"w60-q0","l":6,"lvl":"quiz","type":"choice","q":"y'' + 4y = 8 теңдеуінің тұрақты дербес шешімі:","o":["1","2","4","8"],"a":1,"e":"4A = 8, A = 2."},{"id":"w60-q1","l":6,"lvl":"quiz","type":"choice","q":"y'' − y = e^(2x) үшін y_p түрі:","o":["Ae^(2x)","Axe^(2x)","Ae^x","Axe^x"],"a":0,"e":"Түбірлер ±1; 2 түбір емес."},{"id":"w60-q2","l":6,"lvl":"quiz","type":"choice","q":"y'' − y = e^x үшін y_p түрі:","o":["Ae^x","Axe^x","Ax²e^x","A"],"a":1,"e":"r = 1 түбір: резонанс, s = 1."},{"id":"w60-q3","l":6,"lvl":"quiz","type":"choice","q":"y'' + y = cos x теңдеуінің дербес шешімінің түрі:","o":["A cos x","A cos x + B sin x","x(A cos x + B sin x)","Ax cos x"],"a":2,"e":"±i сипаттамалық түбір: резонанс."},{"id":"w60-q4","l":6,"lvl":"quiz","type":"choice","q":"y'' + 4y = cos 2t, y(0) = y'(0) = 0 шешімі:","o":["(t/4) sin 2t","(1/4) cos 2t","t cos 2t","(1/3)(cos t − cos 2t)"],"a":0,"e":"Резонанс: y = t sin(ωt)/(2ω), ω = 2."},{"id":"w60-q5","l":6,"lvl":"quiz","type":"choice","q":"Тұрақтыны вариациялауда u₁' неге тең?","o":["y₂f/W","−y₂f/W","y₁f/W","−y₁f/W"],"a":1,"e":"Крамер ережесі: u₁' = −y₂f/W."},{"id":"w60-q6","l":6,"lvl":"quiz","type":"choice","q":"Үйкелісі бар жүйеде (b > 0) уақыт өткенде шешімнің қай бөлігі өшеді?","o":["y_p","y_h","екеуі де","ешқайсысы"],"a":1,"e":"Біртекті шешімнің нақты бөлігі теріс түбірлерде e^(−bt/2) бойынша өшеді."},{"id":"w60-q7","l":6,"lvl":"quiz","type":"choice","q":"y'' + 2y' + 5y = cos 2x тұрақты күйінің амплитудасы:","o":["1/17","1/√17","4/17","1/5"],"a":1,"e":"|p(2i)| = |1 + 4i| = √17."},{"id":"m9-7-tf-sys:0","l":7,"lvl":"easy","type":"tf","ctx":"Жүйелер туралы. Әр пікірді бағалаңыз.","q":"$y''+by'+cy=0$ теңдеуін $x_1=y$, $x_2=y'$ арқылы екі теңдеулі жүйеге келтіруге болады.","a":true,"e":"Ақиқат: $x_1'=x_2$, $x_2'=-cx_1-bx_2$."},{"id":"m9-7-tf-sys:1","l":7,"lvl":"easy","type":"tf","ctx":"Жүйелер туралы. Әр пікірді бағалаңыз.","q":"$A\\mathbf v=\\lambda\\mathbf v$ теңдеуінде $\\mathbf v=\\mathbf 0$ меншікті вектор бола алады.","a":false,"e":"Жалған: меншікті вектор нөлден өзгеше болуы тиіс."},{"id":"m9-7-tf-sys:2","l":7,"lvl":"easy","type":"tf","ctx":"Жүйелер туралы. Әр пікірді бағалаңыз.","q":"Матрицаның ізі меншікті мәндердің қосындысына тең.","a":true,"e":"Ақиқат: $\\lambda_1+\\lambda_2=\\tau$ (Виет)."},{"id":"m9-7-tf-sys:3","l":7,"lvl":"easy","type":"tf","ctx":"Жүйелер туралы. Әр пікірді бағалаңыз.","q":"Центр асимптотикалық орнықты.","a":false,"e":"Жалған: траектория нөлге жақындамайды, тұйық орбитамен жүреді."},{"id":"m9-7-choice-mat:0","l":7,"lvl":"easy","type":"choice","ctx":"Жүйенің матрицасы. Дұрыс жауапты таңдаңыз.","q":"$y''+5y'+6y=0$ теңдеуін $x_1=y$, $x_2=y'$ арқылы жүйеге келтіргенде матрица:","o":["$\\begin{pmatrix}0&1\\\\-6&-5\\end{pmatrix}$","$\\begin{pmatrix}0&1\\\\6&5\\end{pmatrix}$","$\\begin{pmatrix}1&0\\\\-5&-6\\end{pmatrix}$","$\\begin{pmatrix}-5&-6\\\\1&0\\end{pmatrix}$"],"a":0,"e":"$x_1'=x_2$, $x_2'=-6x_1-5x_2$."},{"id":"m9-7-num-trdet:0","l":7,"lvl":"easy","type":"num","ctx":"Із және анықтауыш. Жауапты санмен жазыңыз.","q":"$A=\\begin{pmatrix}2&1\\\\1&2\\end{pmatrix}$ үшін $\\tau=\\ ?$","a":4},{"id":"m9-7-num-trdet:1","l":7,"lvl":"easy","type":"num","ctx":"Із және анықтауыш. Жауапты санмен жазыңыз.","q":"Сол матрица үшін $\\Delta=\\det A=\\ ?$","a":3},{"id":"m9-7-num-eig:0","l":7,"lvl":"medium","type":"num","ctx":"Меншікті мән. Жауапты санмен жазыңыз.","q":"$A=\\begin{pmatrix}1&2\\\\3&0\\end{pmatrix}$ матрицасының ең үлкен меншікті мәні?","a":3},{"id":"m9-7-mat-Av:0","l":7,"lvl":"medium","type":"matrix","ctx":"Меншікті векторды тексеру. Векторды баған түрінде жазыңыз.","q":"$A=\\begin{pmatrix}1&2\\\\3&0\\end{pmatrix}$, $\\mathbf v=\\begin{pmatrix}1\\\\1\\end{pmatrix}$. $A\\mathbf v=\\ ?$ (бұл $\\lambda\\mathbf v$ болады)","name":"$A\\mathbf v=$","a":[[3],[3]]},{"id":"m9-7-expr-x1:0","l":7,"lvl":"medium","type":"expr","ctx":"Жүйенің шешімі. Өрнекті $t$ арқылы жазыңыз.","q":"$\\mathbf x'=\\begin{pmatrix}1&2\\\\3&0\\end{pmatrix}\\mathbf x$, $\\mathbf x(0)=(7;2)$. $x_1(t)=\\ ?$","vars":["t"],"dom":[-1,1],"a":"5*exp(3*t)+2*exp(-2*t)"},{"id":"m9-7-num-disc2:0","l":7,"lvl":"medium","type":"num","ctx":"Дискриминант. Жауапты санмен жазыңыз.","q":"$A=\\begin{pmatrix}-1&1\\\\-1&-1\\end{pmatrix}$ үшін $\\mathcal D=\\tau^2-4\\Delta=\\ ?$","a":-4},{"id":"m9-7-choice-class:0","l":7,"lvl":"medium","type":"choice","ctx":"Тепе-теңдіктің түрі. Дұрыс жауапты таңдаңыз.","q":"$A=\\begin{pmatrix}1&2\\\\3&2\\end{pmatrix}$ ($\\tau=3$, $\\Delta=-4$) үшін нөлдік тепе-теңдік:","o":["орнықты түйін","ершік","центр","орнықты спираль"],"a":1,"e":"$\\Delta<0$ ⇒ ершік ($\\lambda=4,-1$)."},{"id":"m9-7-choice-class:1","l":7,"lvl":"medium","type":"choice","ctx":"Тепе-теңдіктің түрі. Дұрыс жауапты таңдаңыз.","q":"$A=\\begin{pmatrix}0&1\\\\-4&0\\end{pmatrix}$ үшін нөлдік тепе-теңдік:","o":["ершік","орнықсыз түйін","центр","орнықты түйін"],"a":2,"e":"$\\tau=0$, $\\Delta=4>0$, $\\lambda=\\pm2i$: центр."},{"id":"m9-7-expr-x2:0","l":7,"lvl":"hard","type":"expr","ctx":"Спираль шешімі. Өрнекті $t$ арқылы жазыңыз.","q":"$\\mathbf x'=\\begin{pmatrix}-1&2\\\\-2&-1\\end{pmatrix}\\mathbf x$, $\\mathbf x(0)=(1;0)$. $x_2(t)=\\ ?$","vars":["t"],"dom":[0,2],"a":"-exp(-t)*sin(2*t)"},{"id":"m9-7-num-omega:0","l":7,"lvl":"hard","type":"num","ctx":"Тербеліс жиілігі. Жауапты санмен жазыңыз.","q":"$x'=2x-xy$, $y'=-3y+xy$ жүйесінің $(3;2)$ маңындағы кіші тербелістің бұрыштық жиілігі $\\omega=\\ ?$","a":"sqrt(6)","tol":0.001},{"id":"m9-7-num-H:0","l":7,"lvl":"hard","type":"num","ctx":"Сақталатын шама. Жауапты өрнек түрінде жазуға болады.","q":"$H=x-3\\ln x+y-2\\ln y$. $H(3;2)=\\ ?$","a":"5-3*log(3)-2*log(2)","tol":0.001},{"id":"m9-7-tf-stab:0","l":7,"lvl":"hard","type":"tf","ctx":"Орнықтылық. Әр пікірді бағалаңыз.","q":"$\\tau<0$ болса, нөлдік тепе-теңдік әрдайым асимптотикалық орнықты.","a":false,"e":"Жалған: $\\Delta<0$ болса, ершік. Мысалы $\\mathrm{diag}(-3;1)$: $\\tau=-2$, бірақ $\\lambda=1>0$."},{"id":"m9-7-tf-stab:1","l":7,"lvl":"hard","type":"tf","ctx":"Орнықтылық. Әр пікірді бағалаңыз.","q":"$\\tau<0$ және $\\Delta>0$ болса, нөл асимптотикалық орнықты.","a":true,"e":"Ақиқат: екі меншікті мәннің нақты бөлігі теріс."},{"id":"m9-7-tf-stab:2","l":7,"lvl":"hard","type":"tf","ctx":"Орнықтылық. Әр пікірді бағалаңыз.","q":"Лотка-Вольтерра жүйесінде $H=dx-c\\ln x+by-a\\ln y$ шамасы траектория бойында өзгермейді.","a":true,"e":"Ақиқат: $dH/dt=0$ (4-қорыту)."},{"id":"m9-7-mat-v2:0","l":7,"lvl":"hard","type":"matrix","ctx":"Екінші меншікті вектор. Векторды баған түрінде жазыңыз.","q":"$A=\\begin{pmatrix}1&2\\\\3&0\\end{pmatrix}$, $\\mathbf v_2=\\begin{pmatrix}2\\\\-3\\end{pmatrix}$. $A\\mathbf v_2=\\ ?$ (бұл $\\lambda_2\\mathbf v_2$ болуы керек)","name":"$A\\mathbf v_2=$","a":[[-4],[6]]},{"id":"m9-7-choice-spiral:0","l":7,"lvl":"hard","type":"choice","ctx":"Спиральдың мінезі. Дұрыс пікірлерді белгілеңіз.","q":"Меншікті мәндері $-1\\pm2i$ болатын жүйе үшін қайсысы ақиқат?","o":["траектория нөл маңында айналады","шешім нөлге ұмтылады","траектория тұйық эллипс","бір айналым уақыты $\\pi$"],"a":[0,1,3],"e":"$\\alpha=-1<0$: спираль нөлге жақындайды; $\\beta=2$: период $2\\pi/\\beta=\\pi$. Тұйық эллипс тек $\\alpha=0$ болғанда."},{"id":"m9-7-num-tank2:0","l":7,"lvl":"hard","type":"num","ctx":"Екі ыдыс. Жауапты ондық бөлшекпен жазыңыз.","q":"$x'=-0{,}05x+0{,}05y$, $y'=0{,}05x-0{,}05y$ жүйесінің матрицасының ізі қанша? (меншікті мәндері $0$ және $\\tau$)","a":-0.1},{"id":"w61-q0","l":7,"lvl":"quiz","type":"choice","q":"y'' + 4y = 0 теңдеуінің жүйедегі матрицасы (x₁ = y, x₂ = y'):","o":["((0, 1), (−4, 0))","((0, 1), (4, 0))","((1, 0), (0, −4))","((0, −4), (1, 0))"],"a":0,"e":"x₁' = x₂, x₂' = −4x₁."},{"id":"w61-q1","l":7,"lvl":"quiz","type":"choice","q":"A = ((1, 2), (3, 0)) матрицасының меншікті мәндері:","o":["3 және −2","1 және 2","6 және −1","2 және −3"],"a":0,"e":"λ² − λ − 6 = 0, λ = 3, −2."},{"id":"w61-q2","l":7,"lvl":"quiz","type":"choice","q":"λ = −1 ± 2i болғанда нөлдік тепе-теңдік:","o":["орнықты спираль","орнықсыз спираль","центр","ершік"],"a":0,"e":"Нақты бөлік −1 < 0: спираль нөлге жақындайды."},{"id":"w61-q3","l":7,"lvl":"quiz","type":"choice","q":"τ = 0, Δ = 9 болса тепе-теңдік:","o":["ершік","центр","орнықты түйін","орнықсыз түйін"],"a":1,"e":"λ = ±3i: таза жорамал, центр."},{"id":"w61-q4","l":7,"lvl":"quiz","type":"choice","q":"Қай жағдайда нөлдік тепе-теңдік ершік?","o":["Δ > 0","Δ < 0","τ < 0","τ = 0"],"a":1,"e":"Δ = λ₁λ₂ < 0: меншікті мәндердің таңбалары әртүрлі."},{"id":"w61-q5","l":7,"lvl":"quiz","type":"choice","q":"y'' + 5y' + 4y = 0 жүйесінде нөлдік тепе-теңдік:","o":["орнықты түйін","центр","ершік","спираль"],"a":0,"e":"λ = −1, −4: екеуі де теріс нақты."},{"id":"w61-q6","l":7,"lvl":"quiz","type":"choice","q":"x' = x(2 − y), y' = y(−3 + x) жүйесінің нөлдік емес тепе-теңдігі:","o":["(2, 3)","(3, 2)","(−3, 2)","(0, 3)"],"a":1,"e":"2 − y = 0 ⇒ y = 2; −3 + x = 0 ⇒ x = 3."},{"id":"w61-q7","l":7,"lvl":"quiz","type":"choice","q":"Лотка-Вольтерра жүйесінің H(x, y) шамасы:","o":["уақытпен өседі","уақытпен кемиді","траектория бойында тұрақты","әрқашан нөл"],"a":2,"e":"dH/dt = 0, сондықтан орбиталар тұйық."}];
